// Controlled classical challenges.
//
// A challenge is a secp256k1 public point P = d·G whose private scalar d was generated by
// THIS server and deliberately restricted to [1, 2^bits). It is a puzzle we set ourselves.
// It is not a wallet, nobody's funds sit behind it, and the coordinator only ever hands out
// points it generated. Solving one proves "a k-bit interval of the curve can be searched",
// nothing more, and every solve is checked here with d·G == P.

import { mul, eq, hex, big, compress, onCurve, mod, order } from './secp.js';
import { rng } from './prng.js';

export const MIN_BITS = 8;
export const MAX_BITS = 256;

// Distinguished-point bits: the walker reports a point when the low dpBits of x are zero.
// Spacing grows with the challenge so the stored table stays around 2^(bits/2 - dp) rows;
// the floor keeps tiny challenges from reporting every single step.
export function dpBitsFor(bits) {
  return Math.max(2, Math.min(18, Math.floor(bits / 2) - 6));
}

// Number of jump sizes {2^0 .. 2^(J-1)} so the mean jump is about 2^(bits/2 - 2).
export function jumpCountFor(bits) {
  const target = 2 ** (bits / 2 - 2);
  let J = 1;
  while ((2 ** J - 1) / J < target && J < 120) J++;
  return Math.max(J, 2);
}

// Expected total steps for the parallel kangaroo with uniform starts: about 2.8·sqrt(2^bits).
export function expectedSteps(bits) {
  return Math.round(2.83 * 2 ** (bits / 2));
}

// Deterministic challenge from (bits, secretSeed). The secret seed stays on the server;
// the public part is everything a worker needs.
export function makeChallenge(bits, secretSeed) {
  if (!Number.isInteger(bits) || bits < MIN_BITS || bits > MAX_BITS) throw new Error('bad bits');
  const r = rng('challenge:' + bits + ':' + secretSeed);
  const span = (1n << BigInt(bits)) - 1n;
  const d = 1n + (r.big(bits + 64) % span); // uniform in [1, 2^bits - 1]
  const P = mul(d);
  return {
    bits,
    d,
    public: {
      bits,
      x: hex(P.x),
      y: hex(P.y),
      compressed: compress(P),
      dpBits: dpBitsFor(bits),
      jumpCount: jumpCountFor(bits),
      expectedSteps: expectedSteps(bits),
    },
  };
}

// Independent verification: does the claimed scalar reproduce the public point?
export function verifySolution(pub, dHex) {
  if (typeof dHex !== 'string' || dHex.length === 0 || dHex.length > 64 || !/^[0-9a-fA-F]+$/.test(dHex)) return { ok: false, reason: 'not hex' };
  if (!pub || !Number.isInteger(pub.bits) || pub.bits < MIN_BITS || pub.bits > MAX_BITS) return { ok: false, reason: 'bad challenge' };
  let d;
  try { d = big(dHex); } catch { return { ok: false, reason: 'not hex' }; }
  if (d <= 0n || d >= 1n << BigInt(pub.bits)) return { ok: false, reason: 'out of interval' };
  const P = { x: big(pub.x), y: big(pub.y) };
  if (!onCurve(P)) return { ok: false, reason: 'public point not on curve' };
  const Q = mul(d);
  return eq(P, Q) ? { ok: true } : { ok: false, reason: 'd·G != P' };
}

// Tame position t = b + D_t is an absolute scalar; wild position w = r + D_w is an offset
// from d. Same point reached means b + D_t = d + r + D_w, so d = tamePos - wildPos.
export function solveFromCollision(tamePos, wildPos, pub) {
  const d = mod(tamePos - wildPos, order);
  if (d <= 0n) return null;
  return verifySolution(pub, hex(d)).ok ? d : null;
}
